const snippets={"Python": ["from typing import List", "from collections import Counter", "from heapq import heappush, heappop", "", "class Solution:", "", "    def topKFrequent(self, nums: List[int], k: int) -> List[int]:", "        cnt = Counter()", "        for x in nums:", "            cnt[x] += 1", "        pq = []", "        for (x, count) in cnt.items():", "            heappush(pq, (count, x))", "            if len(pq) > k:", "                heappop(pq)", "        return [x for (count, x) in pq]"], "Java": ["import java.util.*;", "class Solution {", "    public int[] topKFrequent(int[] nums, int k) {", "        Map<Integer, Integer> cnt = new HashMap<>();", "        for (int x : nums) {", "            cnt.merge(x, 1, Integer::sum);", "        }", "        PriorityQueue<Map.Entry<Integer, Integer>> pq", "            = new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));", "        for (var e : cnt.entrySet()) {", "            pq.offer(e);", "            if (pq.size() > k) {", "                pq.poll();", "            }", "        }", "        return pq.stream().mapToInt(Map.Entry::getKey).toArray();", "    }", "}"]};
